  .rowline{display:grid;grid-template-columns:1fr 2fr 1fr;gap:min(2vw,3.556vh) 2vw;padding:2.2vh 0;border-top:1px solid currentColor;align-items:center;border-color:rgba(127,127,127,.25)}
