  .frame.grid-2-6-6,
  .frame.grid-2-8-4,
  .frame.grid-3-3,
  .frame.grid-6{display:grid}

  /* ---------- 标题层级（API 名称，衬线为主） ---------- */
  .h-hero{
    font-family:var(--serif-zh);
    font-weight:900;
    font-size:min(10vw,17.78vh);
    line-height:.96;
    letter-spacing:-.02em;
  }
  .h-xl{
    font-family:var(--serif-zh);
    font-weight:700;
    font-size:min(6.2vw,11.02vh);
    line-height:1.08;
    letter-spacing:-.01em;
  }
  .h-sub{
    font-family:var(--serif-zh);
    font-weight:500;
    font-size:min(3.1vw,5.511vh);
    line-height:1.25;
