  .h-hero-en,.h-xl-en{font-family:var(--serif-en);letter-spacing:-.025em}

  /* ---------- lead 引语 ---------- */
  .lead{
    font-family:var(--serif-zh);
    font-weight:400;
    font-size:1.75vw;
    line-height:1.5;
    opacity:.86;
  }

  /* ---------- meta-row 底部元数据 ---------- */
  .meta-row{
    display:flex;
    gap:1.2em;
    align-items:baseline;
    flex-wrap:wrap;
    font-family:var(--mono);
    font-size:max(min(14px,1.944vh),.92vw);
    letter-spacing:.16em;
    text-transform:uppercase;
    opacity:.6;
  }

  /* ---------- stat-card（数据大字报用） ---------- */
  .stat-card{
    display:flex;
    flex-direction:column;
    gap:.8vh;
    align-items:flex-start;
    padding-top:1.6vh;
